require_once __DIR__.'/includes/db.php';require_once __DIR__.'/includes/auth.php';require_once __DIR__.'/includes/permissions.php';require_once __DIR__.'/includes/icons.php';require_once __DIR__.'/includes/novedades_semanales_common.php';require_once __DIR__.'/includes/reporting.php';require_once __DIR__.'/includes/comments_repository.php';
