$db=clear_db();$ready=$db->ok();$reportReady=$ready&&ns_report_ready($db)&&permissions_can_menu('novedades_semanales_reporte');$sources=clear_comments_sources();$source=trim((string)($_GET['origen']??''));if(!isset($sources[$source]))$source='';$q=ns_clean($_GET['q']??'',200);$from=ns_parse_date($_GET['desde']??'');$to=ns_parse_date($_GET['hasta']??'');
