function cc_date($value,$dateOnly=false){$value=trim((string)$value);if($value==='')return '—';try{$d=new DateTimeImmutable($value);return $d->format($dateOnly?'d/m/Y':'d/m/Y H:i');}catch(Exception $e){return $value;}}
function cc_query($page){$query=$_GET;$query['pagina']=$page;return http_build_query($query);}
function cc_installation_type($origin,$subject,$context){$value=strtoupper(trim((string)$subject).' '.trim((string)$context));if(strpos($value,'POZO:')!==false||$origin==='pozos')return 'Pozo';if(strpos($value,'BATERIA:')!==false||strpos($value,'BATERÍA:')!==false||strpos($value,'INSTALACION:')!==false||strpos($value,'INSTALACIÓN:')!==false)return 'Batería';if($origin==='instalaciones')return 'Instalación';return '—';}
